<template>
  <main class="story-page">
	<div v-if="loading" class="story-page__loading"><span></span><strong>正在加载故事……</strong></div>
	<template v-else-if="archive">
	  <div class="story-workspace" :class="{ 'story-workspace--raw': rawOpen }">
		<Transition name="raw-pane"><section v-if="rawOpen" class="raw-pane">
		  <header><div><strong>原始语法</strong><small :class="{ error: rawError }">{{ rawError || (rawPending ? '等待补全当前标签…' : '已实时同步到图形预览') }}</small></div><nav><button @click="downloadRaw">下载语法</button><button class="primary" @click="closeRawEditor">返回图形编辑</button></nav></header>
		  <StoryScriptEditor v-model="rawText" :error="rawError" />
		</section></Transition>
		<div class="story-visual"><StoryEditor :archive="archive" :asset-url="assetUrl" :raw-active="rawOpen" @change="onChange" @download="download" @legacy-text="downloadLegacyText" @html="downloadPerformanceHtml" @word="downloadWord" @long-image="openLongImageExport" @preview="playerVisible=true" @raw="toggleRawEditor" @import="fileInput?.click()" @clear="clearDraft" @sync="syncStorySource" /></div>
	  </div>
	  <StoryPlayer :show="playerVisible" :archive="archive" :asset-url="assetUrl" :image-export-request="imageExportRequest" @change="onChange" @raw="openRawFromPlayer" @close="playerVisible=false" />
	</template>
    <section v-else class="story-page__error"><h2>故事加载失败</h2><p>{{ errorText }}</p><button @click="reloadPage">重试</button></section>
    <input ref="fileInput" hidden type="file" accept=".ssp,.story.txt,text/plain" @change="importFile" />
  </main>
</template>

<script setup lang="ts">
import { strFromU8, unzlibSync } from "fflate";
import { parquetReadObjects } from "hyparquet";
import { compressors } from "hyparquet-compressors";
import { asyncBufferFrom } from "hyperparam";
import { debounce } from "lodash-es";
import { onBeforeUnmount, onMounted, ref, toRaw, watch } from "vue";
import StoryEditor from "~/components/story/StoryEditor.vue";
import StoryPlayer from "~/components/story/StoryPlayer.vue";
import StoryScriptEditor from "~/components/story/StoryScriptEditor.vue";
import { logMan } from "~/logManager/logManager";
import { deleteLocalStoryDraft, loadLocalStoryDraft, saveLocalStoryDraft } from "~/story/local-storage";
import { normalizeStoryDocument, storyFromLogItems } from "~/story/model";
import { createStoryPackage, readStoryPackage } from "~/story/package";
import { createPerformanceHtml } from "~/story/standalone-performance";
import { parseStoryScript, serializeStoryScript } from "~/story/raw-script";
import { mergeStorySource } from "~/story/sync";
import type { StoryArchive, StoryAssetRef } from "~/story/types";
import { storyPalette } from "~/story/palette";
import { storyAvatarUrl } from "~/story/avatar";
import { useStore } from "~/store";
import { applyQQImageRKeyReplacement, shouldApplyQQImageRKeyReplacement } from "~/utils";
import { exportFileDocx } from "~/utils/exporter";

const store = useStore();
const archive = ref<StoryArchive>(); const loading = ref(true); const errorText = ref(""); const playerVisible = ref(false); const imageExportRequest = ref(0); const fileInput = ref<HTMLInputElement>();
const rawOpen = ref(false); const rawText = ref(""); const rawError = ref(""); const rawPending = ref(false); const legacyCompatible = ref(true); let applyingRaw = false;
const objectUrls = new Map<string,string>();
const pageParams = new URLSearchParams(location.search); const sourceKey = pageParams.get("key") || (pageParams.get("adminProject") ? `admin-project:${pageParams.get("adminProject")}` : "local");
const draftKey = `story:${location.origin}/story?key=${sourceKey}`;
let sourceFingerprint = "";
function storyFingerprint(value:StoryArchive){return serializeStoryScript(value)}
const saveDraft = debounce(async(value:StoryArchive)=>{try{if(!sourceFingerprint)return;if(storyFingerprint(value)===sourceFingerprint){await deleteLocalStoryDraft(draftKey);return}await saveLocalStoryDraft(draftKey,value)}catch(error){console.error(error)}},500);
let loadedAdvancedProject = false;

function assetUrl(id:string){const existing=objectUrls.get(id);if(existing)return existing;const bytes=archive.value?.assets.get(id);if(!bytes)return id;const refs:StoryAssetRef[]=[...(archive.value?.document.characters.map(c=>c.avatar).filter(Boolean) as StoryAssetRef[]),...(archive.value?.document.messages.flatMap(m=>m.kind!=='text'?[m.asset]:[])||[])];const url=URL.createObjectURL(new Blob([bytes],{type:refs.find(a=>a.id===id)?.mime||'application/octet-stream'}));objectUrls.set(id,url);return url}
function publishCompatibility(){window.dispatchEvent(new CustomEvent('lorana-story-compatibility',{detail:{legacyCompatible:legacyCompatible.value}}))}
function onChange(value:StoryArchive){archive.value=value;legacyCompatible.value=false;publishCompatibility();saveDraft(value);if(rawOpen.value&&!applyingRaw)rawText.value=serializeStoryScript(value)}
function reloadPage(){location.reload()}
function openLongImageExport(){playerVisible.value=true;imageExportRequest.value+=1}
async function applyRKey(text:string){if(!shouldApplyQQImageRKeyReplacement(text))return text;try{return applyQQImageRKeyReplacement(text,await store.tryFetchRKey())}catch{return text}}
function decodeProjectMeta(value:string){const normalized=value.replaceAll("-","+").replaceAll("_","/");const raw=atob(normalized+"=".repeat((4-normalized.length%4)%4));return JSON.parse(new TextDecoder().decode(Uint8Array.from(raw,character=>character.charCodeAt(0))))}

async function loadRemote(){
  const adminProject=pageParams.get("adminProject");if(adminProject){const response=await fetch(`/admin/api/projects/${encodeURIComponent(adminProject)}`,{cache:'no-store',credentials:'same-origin'});if(!response.ok)throw new Error(response.status===401||response.status===403?'需要管理员账号才能打开用户工程副本':'用户工程副本不存在');loadedAdvancedProject=true;if((response.headers.get('content-type')||'').startsWith('application/vnd.lorana-tales.story+zip')){decodeProjectMeta(response.headers.get('x-lorana-project-meta')||'');return readStoryPackage(await response.blob())}const project=await response.json();const packed=project.document;if(typeof packed?.language!=='string')throw new Error('用户工程副本格式无效');const assets=new Map<string,Uint8Array>((packed.assets||[]).map(([id,value]:[string,string])=>[id,Uint8Array.from(atob(value),character=>character.charCodeAt(0))]));const base={document:storyFromLogItems([],[],{title:project.title||'用户工程',assets}),assets};return parseStoryScript(packed.language,base)}
  const key=pageParams.get("key");const password=location.hash.slice(1);let title="新故事";let text="";
  if(key&&password){const record=await store.tryFetchLog(key,password) as {client:string;data:string;name:string;updated_at?:string};title=record.name||title;if(record.client==='Parquet'){const bytes=Uint8Array.from(atob(record.data),c=>c.charCodeAt(0));const file=await asyncBufferFrom({file:new File([bytes],'source.parquet'),byteLength:bytes.byteLength});const rows=await parquetReadObjects({file,compressors});text=JSON.stringify({items:rows.map(row=>({...row,id:Number(row.id),time:Number(row.time),commandId:Number(row.commandId)})),version:105})}else{text=strFromU8(unzlibSync(Uint8Array.from(atob(record.data),c=>c.charCodeAt(0))))}text=await applyRKey(text);const parsed=logMan.parse(text);if(!parsed)throw new Error('远程日志格式无法解析');const assets=new Map<string,Uint8Array>();return{document:storyFromLogItems(parsed.items,[...parsed.charInfo.values()],{title,sourceKey:key,sourceRevision:record.updated_at,assets}),assets}}
  const assets=new Map<string,Uint8Array>();return{document:storyFromLogItems([],[],{title,assets}),assets};
}

async function download(){if(!archive.value)return;const blob=await createStoryPackage(archive.value);const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`${archive.value.document.title.replace(/[\\/:*?"<>|]/g,'_')||'故事'}.ssp`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadLegacyText(){if(!archive.value)return;const items=archive.value.document.messages.map((message,index)=>{const role=archive.value!.document.characters.find(item=>item.id===message.characterId);const text=message.kind==='text'?message.text:message.kind==='image'?'【图片】':`【语音】${message.caption?` ${message.caption}`:''}`;return{...(message.sourceItem||{}),id:index+1,nickname:role?.name||'未知角色',IMUserId:role?.imUserId||'',time:message.time||Date.now(),timeText:message.timeText,message:text,isDice:!!role?.isDice,commandId:Number(message.sourceItem?.commandId||0),color:role?.color||'#607D8B',role:role?.isNarrator?'主持人':'角色'}});saveBlob(new Blob([JSON.stringify({items,version:105},null,2)],{type:'text/plain;charset=utf-8'}),`${safeFilename(archive.value.document.title)}-传统日志.txt`)}
const escapeHtml=(value:unknown)=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]!));
const safeFilename=(value:string)=>value.replace(/[\\/:*?"<>|]/g,'_').trim()||'故事';
function saveBlob(blob:Blob,name:string){const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function blobDataUrl(blob:Blob){return new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
async function embeddedAsset(ref?:StoryAssetRef){if(!ref||!archive.value)return'';const local=archive.value.assets.get(ref.id);if(local)return blobDataUrl(new Blob([local],{type:ref.mime||'application/octet-stream'}));const source=ref.sourceUrl||ref.id;try{const url=new URL(source,location.href);const response=await fetch(url);if(!response.ok)throw new Error(String(response.status));return blobDataUrl(await response.blob())}catch{return''}}
async function embeddedAvatar(character:StoryArchive['document']['characters'][number]){if(character.avatar)return embeddedAsset(character.avatar);if(character.imUserId)try{const response=await fetch(storyAvatarUrl(character.imUserId,character.name));if(response.ok)return blobDataUrl(await response.blob())}catch{return''}return''}
async function downloadPerformanceHtml(){if(!archive.value)return;const html=await createPerformanceHtml(archive.value,embeddedAsset,embeddedAvatar);saveBlob(new Blob([html],{type:'text/html;charset=utf-8'}),`${safeFilename(archive.value.document.title)}-演出.html`)}
async function downloadHtml(){if(!archive.value)return;const current=archive.value;const avatars=new Map<string,string>();for(const character of current.document.characters)avatars.set(character.id,await embeddedAvatar(character));const parts:string[]=[];for(const message of current.document.messages){const character=current.document.characters.find(item=>item.id===message.characterId);const side=character?.position||'left';const palette=storyPalette(message.bubblePaletteId||character?.bubblePaletteId||character?.paletteId);const bubble=palette?.bubbleDark||'#182120';const textColor=palette?.textDark||'#ffffff';const avatar=avatars.get(message.characterId)||'';let body='';if(message.kind==='text')body=`<div class="text">${escapeHtml(message.text).replace(/\n/g,'<br>')}</div>`;else if(message.kind==='image'){const src=await embeddedAsset(message.asset);body=src?`<img src="${src}" alt="${escapeHtml(message.alt||'图片')}">`:'<div class="placeholder">【图片】</div>'}else{const src=await embeddedAsset(message.asset);body=`${src?`<audio controls preload="metadata" src="${src}"></audio>`:'<div class="placeholder">【语音】</div>'}${message.caption?`<p class="audio-caption">${escapeHtml(message.caption).replace(/\n/g,'<br>')}</p>`:''}`};parts.push(`<article class="message ${escapeHtml(side)}">${side!=='narrator'?`<span class="avatar">${avatar?`<img src="${avatar}" alt="">`:escapeHtml(character?.name.slice(0,1)||'角')}</span>`:''}<div class="content">${character&&!character.isNarrator?`<small style="color:${escapeHtml(palette?.nameDark||character.color)}">${escapeHtml(character.name)}${current.document.settings.showQqInPreview&&character.imUserId?` · ${escapeHtml(character.imUserId)}`:''}</small>`:''}<div class="bubble" style="--bubble:${escapeHtml(bubble)};--bubble-text:${escapeHtml(textColor)}">${body}</div></div></article>`)}const source=serializeStoryScript(current).replace(/<\/script/gi,'<\\/script');const scriptClose='</'+'script>';const html=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(current.document.title)}</title><style>*{box-sizing:border-box}body{margin:0;background:#0b1110;color:#eef2f1;font:16px/1.55 system-ui,sans-serif}.story{width:min(${current.document.settings.canvasWidth}px,100%);margin:auto;padding:24px 14px}.message{display:flex;gap:10px;align-items:flex-start;margin:10px 0}.message.right{flex-direction:row-reverse;text-align:right}.message.narrator{justify-content:center;text-align:center}.avatar{display:grid;place-items:center;flex:0 0 ${current.document.settings.avatarSize}px;width:${current.document.settings.avatarSize}px;height:${current.document.settings.avatarSize}px;overflow:hidden;border-radius:50%;background:#334342}.avatar img{width:100%;height:100%;object-fit:cover}.content{max-width:${current.document.settings.bubbleMaxWidth}%}.content small{display:block;margin:0 6px 3px;font-weight:650}.bubble{padding:12px 16px;border-radius:18px;background:var(--bubble);color:var(--bubble-text);white-space:pre-wrap;overflow-wrap:anywhere}.bubble img{display:block;max-width:100%;height:auto;border-radius:12px}.bubble audio{width:min(360px,72vw)}.audio-caption{margin:8px 0 0;padding-top:7px;border-top:1px solid #ffffff2b;text-align:left}.placeholder{color:#b7c1bf}.narrator .bubble{border-radius:10px}@media(max-width:600px){.story{padding:14px 8px}.content{max-width:82%}}</style></head><body><main class="story"><h1>${escapeHtml(current.document.title)}</h1>${parts.join('')}</main><script id="lorana-tales-source" type="text/lorana-tales">${source}${scriptClose}</body></html>`;saveBlob(new Blob([html],{type:'text/html;charset=utf-8'}),`${safeFilename(current.document.title)}.html`)}
async function downloadWord(){if(!archive.value)return;const current=archive.value;const rows:string[]=[];for(const message of current.document.messages){const character=current.document.characters.find(item=>item.id===message.characterId);const palette=storyPalette(character?.paletteId);const heading=character?.isNarrator?'':`<p><strong style="color:${escapeHtml(palette?.nameLight||character?.color||'#34413f')}">${escapeHtml(character?.name||'未知角色')}</strong>${character?.imUserId?` <span style="color:#667085">· ${escapeHtml(character.imUserId)}</span>`:''}</p>`;let body='';if(message.kind==='text')body=`<p>${escapeHtml(message.text).replace(/\n/g,'<br>')}</p>`;else if(message.kind==='image'){const src=await embeddedAsset(message.asset);body=src?`<p><img src="${src}" alt="${escapeHtml(message.alt||'图片')}" style="max-width:560px;height:auto"></p>`:'<p>【图片】</p>'}else body=`<p>【语音】${message.caption?` ${escapeHtml(message.caption).replace(/\n/g,'<br>')}`:''}</p>`;rows.push(`${heading}${body}`)}const html=`<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(current.document.title)}</title></head><body><h1>${escapeHtml(current.document.title)}</h1>${rows.join('<hr>')}</body></html>`;await exportFileDocx(html,`${safeFilename(current.document.title)}.docx`)}
function openRawEditor(){if(!archive.value)return;rawText.value=serializeStoryScript(archive.value);rawError.value='';rawPending.value=false;rawOpen.value=true}
function closeRawEditor(){validateRaw.cancel();rawOpen.value=false;rawPending.value=false}
function toggleRawEditor(){rawOpen.value?closeRawEditor():openRawEditor()}
function openRawFromPlayer(){playerVisible.value=false;openRawEditor()}
function rawStructureComplete(value:string){const open=value.lastIndexOf('<');return open<0||open<value.lastIndexOf('>')}
function rawParseBase():StoryArchive{return{document:structuredClone(toRaw(archive.value!.document)),assets:new Map(toRaw(archive.value!.assets))}}
const validateRaw=debounce(()=>{if(!archive.value||!rawOpen.value)return;if(!rawStructureComplete(rawText.value)){rawPending.value=true;rawError.value='';return}rawPending.value=false;try{const parsed=parseStoryScript(rawText.value,rawParseBase());applyingRaw=true;onChange(parsed);rawError.value=''}catch(error){rawError.value=error instanceof Error?error.message:'语法校验失败'}finally{applyingRaw=false}},220)
watch(rawText,()=>{if(rawOpen.value)validateRaw()})
function downloadRaw(){const blob=new Blob([rawText.value||serializeStoryScript(archive.value!)],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`${archive.value?.document.title||'故事'}.story.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importFile(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file||!archive.value)return;try{if(file.name.toLowerCase().endsWith('.ssp')){onChange(await readStoryPackage(file));return}const text=await file.text();if(/<story\s|<role\s|<msg\s/.test(text)){onChange(parseStoryScript(text,rawParseBase()));return}const parsed=logMan.parse(await applyRKey(text));if(!parsed)throw new Error('无法识别该文件；请使用旧版染色器日志、SSP 或 Lorana Tales Story Language');const assets=new Map<string,Uint8Array>();onChange({document:storyFromLogItems(parsed.items,[...parsed.charInfo.values()],{title:file.name.replace(/\.[^.]+$/,''),assets}),assets})}catch(error){alert(error instanceof Error?error.message:'导入失败')}finally{input.value=''}}
async function clearDraft(){if(!confirm('确定删除这个故事在本浏览器保存的全部修改吗？'))return;if(!confirm('再次确认：此操作无法从浏览器恢复，已下载 SSP 不受影响。'))return;await deleteLocalStoryDraft(draftKey);archive.value=await loadRemote();sourceFingerprint=storyFingerprint(archive.value);legacyCompatible.value=!loadedAdvancedProject;publishCompatibility()}
async function syncStorySource(payload:{record:{client:string;data:string;name?:string;updated_at?:string};sourceKey:string;sourceRevision?:string}){if(!archive.value)return;try{let text='';if(payload.record.client==='Parquet'){const bytes=Uint8Array.from(atob(payload.record.data),c=>c.charCodeAt(0));const file=await asyncBufferFrom({file:new File([bytes],'source.parquet'),byteLength:bytes.byteLength});const rows=await parquetReadObjects({file,compressors});text=JSON.stringify({items:rows.map(row=>({...row,id:Number(row.id),time:Number(row.time),commandId:Number(row.commandId)})),version:105})}else{text=strFromU8(unzlibSync(Uint8Array.from(atob(payload.record.data),c=>c.charCodeAt(0))))}const parsed=logMan.parse(await applyRKey(text));if(!parsed)throw new Error('源日志无法解析');const assets=new Map<string,Uint8Array>();const incoming=storyFromLogItems(parsed.items,[...parsed.charInfo.values()],{title:payload.record.name,sourceKey:payload.sourceKey,sourceRevision:payload.record.updated_at||payload.sourceRevision,assets});const merged=mergeStorySource(archive.value.document,incoming);onChange({document:merged.document,assets:new Map([...archive.value.assets,...assets])})}catch(error){alert(error instanceof Error?error.message:'同步源日志失败')}}
function saveShortcut(event:KeyboardEvent){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();download()}}

onMounted(async()=>{window.addEventListener('keydown',saveShortcut);try{archive.value=await loadRemote();sourceFingerprint=storyFingerprint(archive.value);legacyCompatible.value=!loadedAdvancedProject;const draft=await loadLocalStoryDraft(draftKey);if(draft){const normalized={...draft,document:normalizeStoryDocument(draft.document)};if(storyFingerprint(normalized)===sourceFingerprint)await deleteLocalStoryDraft(draftKey);else if(confirm('检测到这个故事在当前浏览器保存的修改，是否恢复？')){archive.value=normalized;legacyCompatible.value=false}}publishCompatibility()}catch(error){console.error(error);errorText.value=error instanceof Error?error.message:'无法加载故事';archive.value=undefined}finally{loading.value=false}});
onBeforeUnmount(()=>{window.removeEventListener('keydown',saveShortcut);saveDraft.cancel();validateRaw.cancel();for(const url of objectUrls.values())URL.revokeObjectURL(url)});
</script>

<style scoped>
.story-page{height:100%;min-height:0;overflow:hidden;background:var(--app-bg);color:var(--control-text)}.story-page__loading,.story-page__error{height:100%;min-height:0;display:grid;place-content:center;justify-items:center;gap:1rem}.story-page__loading span{width:2rem;height:2rem;border:3px solid color-mix(in srgb,var(--control-text) 14%,transparent);border-top-color:var(--focus-color);border-radius:50%;animation:spin .8s linear infinite}.story-page__error button,.raw-pane button{border:0;border-radius:9px;padding:.55rem .75rem;background:var(--control-surface);color:inherit;cursor:pointer}@keyframes spin{to{transform:rotate(360deg)}}
.story-workspace{display:grid;width:100%;height:100%;min-height:0;overflow:hidden;transition:grid-template-columns .24s cubic-bezier(.2,.75,.2,1)}.story-workspace--raw{grid-template-columns:minmax(340px,.9fr) minmax(0,1.1fr)}.story-visual{width:100%;height:100%;min-width:0;min-height:0;overflow:hidden;transition:opacity .2s ease,transform .24s cubic-bezier(.2,.75,.2,1)}.raw-pane{display:grid;grid-template-rows:auto minmax(0,1fr);min-width:0;min-height:0;overflow:hidden;border-right:1px solid #374441;background:#1e1e1e}.raw-pane header{display:flex;align-items:center;justify-content:space-between;gap:1rem;min-height:54px;padding:.55rem .75rem;border-bottom:1px solid #343434;background:#181818}.raw-pane header>div{display:grid;min-width:0}.raw-pane header small{overflow:hidden;color:#73c991;text-overflow:ellipsis;white-space:nowrap;font-size:.72rem}.raw-pane header small.error{color:#f48771}.raw-pane nav{display:flex;gap:.35rem}.raw-pane button.primary{background:#168a92}.raw-pane-enter-active,.raw-pane-leave-active{transition:opacity .22s ease,transform .24s cubic-bezier(.2,.75,.2,1)}.raw-pane-enter-from,.raw-pane-leave-to{opacity:0;transform:translateX(-22px)}
@media(max-width:650px){.story-workspace--raw{grid-template-columns:1fr}.story-workspace--raw .story-visual{position:absolute;visibility:hidden;opacity:0;transform:translateX(14px);pointer-events:none}.raw-pane{border-right:0}.raw-pane header{padding:.45rem .55rem}.raw-pane header small{max-width:42vw}.raw-pane button{padding:.45rem .55rem;font-size:.72rem}}
.story-workspace:has(.raw-pane){grid-template-columns:minmax(340px,.9fr) minmax(0,1.1fr)}
@media(max-width:650px){.story-workspace:has(.raw-pane){grid-template-columns:1fr}.story-workspace:has(.raw-pane) .story-visual{position:absolute;visibility:hidden;opacity:0;transform:translateX(14px);pointer-events:none}}
.raw-pane button.primary{background:var(--primary-bg);color:var(--primary-text)}.raw-pane button.primary:hover{background:var(--primary-hover)}
</style>
